import math
from collections import Counter, defaultdict

def get_stats(train):
    labels = [label for _, label in train]
    unique_labels = sorted(set(labels))
    counts = {l: Counter() for l in unique_labels}
    totals = {l: 0 for l in unique_labels}
    doc_counts = Counter(labels)
    vocab = set()
    for text, label in train:
        tokens = text.lower().split()
        counts[label].update(tokens)
        totals[label] += len(tokens)
        vocab.update(tokens)
    return unique_labels, counts, totals, doc_counts, len(vocab), len(train)

def nb_scores(train, text):
    labels, counts, totals, doc_counts, v_size, n = get_stats(train)
    tokens = text.lower().split()
    scores = {}
    for l in labels:
        log_p = math.log(doc_counts[l] / n)
        for w in tokens:
            if w in counts[l] or True: # smoothing applied
                log_p += math.log((counts[l][w] + 1) / (totals[l] + v_size))
        scores[l] = round(log_p, 3)
    return scores

def nb_classify(train, text):
    scores = nb_scores(train, text)
    return min(scores.keys(), key=lambda l: (-scores[l], l))

REVIEWS = [("zabardast khana bohat acha", "pos"), ("bekaar service thanda khana", "neg"), ("acha taste jaldi delivery", "pos"), ("bura experience late delivery", "neg")]
print(nb_classify(REVIEWS, "khana acha tha"))

